const ReactECharts = dynamic(() => import("echarts-for-react"), { ssr: false });
type DeviceStatus = "online" | "warning" | "offline";
type PortStatus = "up" | "down" | "warning";
type View = "dashboard" | "problems" | "hosts" | "latest" | "topology" | "events" | "monitor";
type Period = "day" | "week" | "month" | "year";

type Port = { id: number; if_index: number; if_name: string; if_descr: string; admin_status: number; oper_status: number; speed_bps: number; last_change: string; status: PortStatus; in_mbps: number; out_mbps: number };
type Device = { id: number; name: string; ip_address: string; device_type: "router" | "switch"; snmp_version: "2c" | "3"; status: DeviceStatus; sys_descr: string; sys_uptime: string; last_seen: string; ports: Port[] };
type TrapEvent = { id: number; occurred_at: string; device: string; ip_address: string; interface: string; event_type: "linkUp" | "linkDown"; severity: "info" | "critical"; message: string };
type TopologyLink = { id: number; local_device_id: number; local_if_index: number; remote_device_name: string; remote_port_name: string; protocol: string; discovered_at: string };

const makePort = (index: number, status: PortStatus, speed = 1_000_000_000): Port => ({
  id: index, if_index: index, if_name: `Gi0/${index}`, if_descr: `GigabitEthernet0/${index}`,
  admin_status: status === "down" ? 2 : 1, oper_status: status === "up" ? 1 : status === "down" ? 2 : 3,
  speed_bps: speed, last_change: index % 3 === 0 ? "18 นาทีที่แล้ว" : "2 วัน 4 ชม. ที่แล้ว", status,
  in_mbps: Number((12 + ((index * 7) % 38) + index / 10).toFixed(1)), out_mbps: Number((7 + ((index * 5) % 23) + index / 10).toFixed(1)),
});

